from pathlib import Path
import json,html
P=Path(__file__).parent;O=P/'out';E=html.escape
b=json.loads((P/'beat-sheet.json').read_text());c=json.loads((P/'captions-bilingual.json').read_text(encoding='utf-8'));f=json.loads((O/'snapshots.json').read_text(encoding='utf-8-sig'))['frames']
cards=[]
for beat,frame in zip(b,f):
    src=Path(frame['path']).relative_to(O).as_posix()
    cards.append(f'<article><img src="{src}"><div><small>{beat["start"]}–{beat["end"]} s · {beat["layout"]}</small><h2>{E(beat["label"])}</h2><p>{E(beat["action"])}</p></div></article>')
rows=''.join(f'<tr><td>{x["start"]:.2f}–{x["end"]:.2f}</td><td>{E(x["en"])}</td><td>{E(x["id"])}</td></tr>' for x in c)
doc='''<!doctype html><html lang="id"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GROWING MEANS — storyboard bilingual</title><style>body{margin:0;background:#101827;color:#EDEAE4;font:17px/1.6 system-ui}main{max-width:1200px;margin:auto;padding:40px 24px}h1{font-size:48px;line-height:1.1}a{color:#C5B69A}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}article{background:#26364C}article img{width:100%}article div{padding:18px}small{color:#C5B69A}table{width:100%;border-collapse:collapse;margin-top:28px}td,th{padding:14px;border-bottom:1px solid #26364C;text-align:left}.note{padding:24px;border:1px solid #718A83;margin:30px 0}@media(max-width:800px){.grid{grid-template-columns:1fr}h1{font-size:34px}table{font-size:14px}}</style><main><p>NAZARVERSE · BRAND V1.0</p><h1>Growing means.<br>Memberi ruang untuk berubah.</h1><p>Storyboard 43,43 detik · HyperFrames · Inggris utama + Indonesia sekunder. Navy, ivory, sand dan sage; DM Sans. Enam adegan, tanpa slide/wipe berulang.</p><section class="grid">'''+''.join(cards)+'''</section><div class="note"><strong>Batas pratinjau</strong><p>Ini still storyboard untuk persetujuan desain, bukan MP4 final. Dua gambar talent adalah uji mask footage baru; produksi akhir wajib menggunakan video talent bergerak dengan mask temporal. Audio sumber tersedia dalam komposisi, tetapi mix final belum dibuat. Keterbacaan dan fase layout ditinjau melalui still, bukan bukti keluwesan playback penuh.</p><p>Rekomendasi: empat adegan full graphics dengan subtitle editorial; pembuka/penutup menampilkan talent dan grafis. Subtitle dua bahasa mempunyai area sendiri. Perpindahan saat ini berupa cut sederhana. Morph halaman-ke-jalur adalah opsi yang belum diterapkan, bukan hasil yang diklaim selesai.</p></div><h2>Subtitle untuk ditinjau</h2><p>Empat koreksi Inggris sudah dikonfirmasi pengguna. Terjemahan Indonesia merupakan terjemahan editorial; waktu kata tambahan masih perlu pemeriksaan dengar pada produksi.</p><table><tr><th>Detik</th><th>English · utama</th><th>Indonesia · sekunder</th></tr>'''+rows+'''</table><p><a href="qa-storyboard.md">Laporan QA dan batas verifikasi</a></p></main></html>'''
(O/'storyboard.html').write_text(doc,encoding='utf-8')
r=json.loads((O/'check.json').read_text(encoding='utf-8-sig'));counts={k:{'errors':v.get('errorCount'),'warnings':v.get('warningCount')} for k,v in r.items() if isinstance(v,dict) and 'findings' in v}
(O/'qa-storyboard.md').write_text('# GROWING MEANS — QA storyboard\n\nBrief: 4 koreksi dikonfirmasi, English + Indonesia, 6 adegan grafis dominan. Brand: palet dan DM Sans sesuai PDF v1.0.\n\nTeknis HyperFrames: '+json.dumps(counts)+'\n\nArtistik: still ditinjau; tanpa slide/wipe. Buku membuka lewat engsel; penanda berpindah; pintu membuka dan daun tumbuh. Morph belum diterapkan. Pilot mask hanya dua frame; kestabilan tepi sepanjang video belum diverifikasi.\n\nBelum final: continuous video alpha, mix ambient/vokal, word-level listening, playback artistik dan QA ekspor. Persetujuan storyboard belum diberikan. Tidak ada MP4 dirender.\n',encoding='utf-8')
m=json.loads((P/'manifest.json').read_text());m['status']='storyboard-ready';m['storyboard']='out/storyboard.html';m['production_pending']=['continuous talent mask','final audio mix','playback QA'];(P/'manifest.json').write_text(json.dumps(m,indent=2)+'\n',encoding='utf-8')
